package main
func add[T ~int8|~int16](a,b T) T { return a+b }
func narrow() int {return 200+int(add(int8(120),int8(9)))}
func wide() int {return 200+int(add(int16(120),int16(9)))}
func pack(xs ...int) []int { return xs }
func packet() int {s:=pack(3,7);s[0]=6;return 10*s[0]+s[1]}
func shared() int {s:=[]int{2,4}; p:=pack(s...); p[1]=7; return 10*s[0]+s[1]}
func emptyPack() bool {return pack()==nil}
func emptySpread() bool {s:=[]int{}; return pack(s...)==nil}
func pair(x int) (int,int) { return x+1,x+3 }
func combine(a,b int) int {return 10*a+b}
func multi() int {return combine(pair(5))}
func multiVar() int {return combineVar(pair(5))}
func combineVar(a int, bs ...int) int {return 10*a+bs[0]}
func set(s []int) int {s[0]=9;return 1}
func get(s []int) int {return s[0]}
func dirty() int {s:=[]int{4}; n:=set(s);return 10*n+s[0]}
func clean() int {s:=[]int{4}; n:=get(s);return 10*n+s[0]}
func nilFn() bool {var f func()int;return f==nil}
func boxedNilFn() bool {var f func()int;var a any=f;return a==nil}
func literalFn() bool {f:=func()int{return 5};return f==nil}
